                // Add the $obj1 (RepresentanteLegal) to the collection in $obj2 (Ciudad)
                $obj2->addRepresentanteLegal($obj1);

            } // if joined row is not null

                // Add objects for joined TipoIdentificacion rows

                $key3 = TipoIdentificacionPeer::getPrimaryKeyHashFromRow($row, $startcol3);
                if ($key3 !== null) {
